insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000001', 'hidratacao-meta-diaria', 'Como calcular sua meta diária de hidratação', 'Volume ideal por peso, sinais de desidratação e rotina prática para manter a hidratação ao longo do dia.', '["Manter uma hidratação adequada é um dos hábitos mais simples e mais subestimados da saúde preventiva. A água participa da termorregulação, transporte de nutrientes, eliminação de resíduos e funcionamento cognitivo. Quando a ingestão fica abaixo do necessário, o corpo compensa temporariamente — mas fadiga, dor de cabeça e queda de foco aparecem cedo.","Uma forma prática de estimar a meta diária é usar cerca de 35 ml por kg de peso corporal, ajustando para clima quente, treinos intensos ou gestação. Atletas e pessoas expostas ao calor podem precisar de 40–45 ml/kg. A sede é um sinal tardio; observe também a cor da urina: amarelo claro indica boa hidratação.","Distribuir a ingestão ao longo do dia evita sobrecarga renal e mantém performance estável. Comece a manhã com um copo de água, inclua frutas ricas em água (melancia, laranja) e evite substituir água por bebidas açucaradas. Café e chá contribuem com moderação, mas não devem ser a única fonte.","Sinais de alerta de desidratação incluem boca seca persistente, tontura ao levantar, pele menos elástica e queda de rendimento nos treinos. Idosos e crianças desidratam com mais rapidez — atenção redobrada nesses grupos.","Para personalizar sua meta, use a ferramenta de hidratação em Ferramentas e acompanhe hábitos no Clube Saúde & Bem. Pequenos ajustes diários geram impacto cumulativo em energia, pele e saúde metabólica."]'::jsonb, 'hidratacao', 'Hidratação', 'Dra. Marina Alves', 'Medicina Preventiva', '6 min', '28 Mai 2026', true, false, '/logo-saude-bem.png', 'Como calcular sua meta diária de hidratação | Guia Saúde & Bem', 'Volume ideal por peso, sinais de desidratação e rotina prática para manter a hidratação ao longo do dia.', 'hidratacao, meta, diaria', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000002', 'agua-energia-cognicao', 'Água, energia e cognição: o que a ciência diz', 'Desidratação leve reduz foco e humor — entenda como a água impacta performance mental.', '["A relação entre água e cognição é robusta na literatura científica. Estudos controlados mostram que perdas de apenas 1–2% do peso corporal em fluidos já reduzem atenção, memória de curto prazo e humor em adultos saudáveis.","O cérebro é composto em grande parte por água. Desidratação leve altera volume cerebral, fluxo sanguíneo e neurotransmissores, o que explica a sensação de ‘neblina mental’ comum no meio da tarde.","Trabalhadores intelectuais e estudantes se beneficiam de garrafas visíveis na mesa e alarmes discretos a cada 60–90 minutos. Combinação de água + proteína no café da manhã potencializa alerta matinal sem depender exclusivamente de cafeína.","Bebidas energéticas mascaram sede e podem piorar desidratação pelo efeito diurético da cafeína em altas doses. Priorize água como base e use café estrategicamente até o meio da manhã.","Monitorar peso antes e depois de treinos longos ajuda a repor fluidos perdidos: cada 1 kg a menos na balança ≈ 1 litro a mais de água nas horas seguintes."]'::jsonb, 'hidratacao', 'Hidratação', 'Dr. Rafael Costa', 'Nutrição Clínica', '5 min', '20 Mai 2026', false, false, '/logo-saude-bem.png', 'Água, energia e cognição: o que a ciência diz | Guia Saúde & Bem', 'Desidratação leve reduz foco e humor — entenda como a água impacta performance mental.', 'agua, energia, cognicao', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000003', 'sono-imunidade-metabolismo', 'Como o sono impacta imunidade e metabolismo', 'Entenda a conexão entre descanso, hormônios, glicemia e saúde metabólica.', '["O sono não é tempo perdido — é quando o corpo repara tecidos, consolida memórias e regula hormônios metabólicos. Durante o sono profundo, a liberação de hormônio do crescimento favorece recuperação muscular e imunidade.","Privação crônica eleva cortisol e reduz sensibilidade à insulina, favorecendo ganho de peso abdominal e resistência metabólica. Uma noite ruim pode elevar glicemia em jejum no dia seguinte, mesmo em pessoas saudáveis.","Células imunes como linfócitos T dependem de ritmo circadiano alinhado. Trabalhadores noturnos apresentam maior incidência de infecções respiratórias — evidência de que o relógio biológico e a imunidade conversam o tempo todo.","Higiene do sono inclui horário fixo, quarto escuro e fresco (18–21 °C), redução de telas 60 minutos antes de deitar e limitação de álcool — que fragmenta o sono REM mesmo quando induz sonolência inicial.","Se insônia persistir por mais de três semanas, busque avaliação profissional. Apneia do sono, refluxo noturno e ansiedade são causas tratáveis que melhoram metabolismo e qualidade de vida."]'::jsonb, 'sono', 'Sono', 'Dr. Rafael Costa', 'Neurociência do Sono', '7 min', '18 Mai 2026', false, false, '/logo-saude-bem.png', 'Como o sono impacta imunidade e metabolismo | Guia Saúde & Bem', 'Entenda a conexão entre descanso, hormônios, glicemia e saúde metabólica.', 'sono, imunidade, metabolismo', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000004', 'higiene-sono-guia', 'Guia prático de higiene do sono', 'Ambiente, rotina e hábitos noturnos para recuperação profunda e consistente.', '["Higiene do sono é o conjunto de hábitos e condições ambientais que sinalizam ao cérebro que é hora de descansar. Não depende de suplementos caros — depende de consistência.","Estabeleça uma janela de sono de 7–9 horas com horários similares inclusive nos fins de semana. O corpo antecipa melhor a produção de melatonina quando o ritmo é previsível.","Transforme os 30 minutos finais do dia em ritual de desaceleração: luz baixa, leitura leve, respiração diafragmática ou alongamento suave. Evite discussões difíceis e notícias estimulantes nesse período.","Invista no ambiente: cortinas blackout, ruído branco se necessário, colchão e travesseiro adequados ao seu biotipo. Temperatura elevada fragmenta o sono profundo.","Cafeína após 14h e refeições pesadas até 2h antes de deitar são inimigos comuns do descanso reparador. Experimente jantar mais cedo por duas semanas e observe diferença na energia matinal."]'::jsonb, 'sono', 'Sono', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '12 Mai 2026', false, false, '/logo-saude-bem.png', 'Guia prático de higiene do sono | Guia Saúde & Bem', 'Ambiente, rotina e hábitos noturnos para recuperação profunda e consistente.', 'higiene, sono, guia', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000005', 'emagrecimento-sustentavel', 'Emagrecimento sustentável: além da balança', 'Déficit calórico inteligente, proteína adequada e hábitos que mantêm resultados.', '["Emagrecimento sustentável não é sprint — é maratona de hábitos compatíveis com sua vida real. Déficit calórico agressivo funciona no curto prazo, mas elevates fome, perda muscular e efeito rebote.","Priorize proteína em cada refeição (1,6–2,2 g/kg em fases de perda de gordura), fibras de vegetais e gorduras boas. Proteína preserva massa magra e aumenta saciedade — aliada estratégica contra o efeito platô.","Movimento diário importa tanto quanto treinos estruturados: caminhadas, escadas e pausas ativas somam gasto energético (NEAT) e melhoram sensibilidade à insulina.","Sono e gestão de estresse são pilares silenciosos: cortisol elevado dificulta perda de gordura abdominal. Sem descanso adequado, a balança pode enganar — peso cai, mas composição corporal piora.","Meça progresso além da balança: circunferência abdominal, fotos mensais, energia e desempenho nos treinos. Tendência de 0,5–1% do peso por semana é meta realista para a maioria dos adultos."]'::jsonb, 'emagrecimento', 'Emagrecimento', 'Dra. Marina Alves', 'Medicina Preventiva', '9 min', '15 Mai 2026', true, false, '/logo-saude-bem.png', 'Emagrecimento sustentável: além da balança | Guia Saúde & Bem', 'Déficit calórico inteligente, proteína adequada e hábitos que mantêm resultados.', 'emagrecimento, sustentavel', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000006', 'plateau-emagrecimento', 'Plateau no emagrecimento: o que fazer', 'Por que a perda de peso estagna e estratégias baseadas em evidências para retomar progresso.', '["Plateau no emagrecimento é frustrante, mas comum após 4–8 semanas de dieta. O corpo reduz gasto energético basal e hormônios como leptina e grelina sinalizam maior fome — adaptação evolutiva, não falha pessoal.","Revise primeiro a aderência real: porções ‘inofensivas’ (azeite, castanhas, sucos) somam calorias. Diário alimentar honesto por 7 dias revela padrões invisíveis.","Ajuste estratégico: pequena redução calórica adicional (100–150 kcal) ou aumento de NEAT (2.000 passos/dia a mais) costuma destravar sem dietas extremas.","Treino de força mantém metabolismo e composição corporal durante déficit. Apenas cardio prolongado pode acelerar perda muscular — combine ambos.","Se plateau persistir com aderência confirmada, converse com nutricionista ou médico sobre tireoide, medicamentos e qualidade do sono. Saúde metabólica exige visão integral."]'::jsonb, 'emagrecimento', 'Emagrecimento', 'Dr. Rafael Costa', 'Nutrição Clínica', '7 min', '8 Mai 2026', false, false, '/logo-saude-bem.png', 'Plateau no emagrecimento: o que fazer | Guia Saúde & Bem', 'Por que a perda de peso estagna e estratégias baseadas em evidências para retomar progresso.', 'plateau, emagrecimento', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000007', 'pressao-arterial-prevencao', 'Pressão arterial: prevenção no dia a dia', 'Hábitos alimentares, movimento e monitoramento para saúde cardiovascular.', '["Hipertensão arterial é principal fator modificável de risco cardiovascular no Brasil. Muitos casos podem ser prevenidos ou controlados com estilo de vida antes de medicamentos — em conjunto com acompanhamento médico.","Redução de sódio (menos ultraprocessados, temperos naturais), aumento de potássio via frutas e vegetais, e moderação de álcool têm efeito mensurável na pressão arterial em semanas.","Atividade aeróbica moderada (150 min/semana) e treino de força complementar melhoram função vascular e reduzem rigidez arterial. Caminhadas rápidas já contam.","Monitorar PA em casa — sentado, braço apoiado, mesma hora — gera histórico útil para consultas. Valores repetidos acima de 130/80 mmHg merecem atenção.","Controle de peso, sono reparador e manejo de estresse completam o pacote preventivo. Saúde cardiovascular é construída em decisões diárias, não apenas em exames anuais."]'::jsonb, 'saude-cardiovascular', 'Saúde Cardiovascular', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '10 Mai 2026', false, false, '/logo-saude-bem.png', 'Pressão arterial: prevenção no dia a dia | Guia Saúde & Bem', 'Hábitos alimentares, movimento e monitoramento para saúde cardiovascular.', 'pressao, arterial, prevencao', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000008', 'colesterol-hdl-triglicerides', 'Colesterol, HDL e triglicerídeos explicados', 'O que os exames significam e como hábitos influenciam o perfil lipídico.', '["Perfil lipídico vai além do ‘colesterol total’. LDL elevado, HDL baixo e triglicerídees altos contam histórias diferentes sobre risco cardiometabólico — e exigem estratégias distintas.","LDL transporta colesterol para tecidos; em excesso com inflamação crônica, favorece placas arteriais. Triglicerídees altos frequentemente refletem excesso de açúcar, álcool e ultraprocessados.","HDL ajuda a remover colesterol das artérias, mas não compensa sozinho um LDL muito elevado. Foco exclusivo em ‘aumentar HDL’ perde o quadro geral.","Fibras solúveis (aveia, linhaça, leguminosas), ômega-3 de peixes ou suplementação orientada, exercício regular e redução de gordura visceral melhoram o perfil lipídico com evidência sólida.","Este conteúdo é educativo — interpretação de exames e metas terapêuticas devem ser individualizadas com seu médico. Clube Saúde & Bem oferece materiais premium sobre prevenção cardiovascular."]'::jsonb, 'saude-cardiovascular', 'Saúde Cardiovascular', 'Dr. Rafael Costa', 'Cardiologia Preventiva', '10 min', '5 Mai 2026', false, true, '/logo-saude-bem.png', 'Colesterol, HDL e triglicerídeos explicados | Guia Saúde & Bem', 'O que os exames significam e como hábitos influenciam o perfil lipídico.', 'colesterol, hdl, triglicerides', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000009', 'pilares-longevidade-2026', 'Os 5 pilares da longevidade que a ciência confirma', 'Descubra os hábitos com maior evidência científica para viver mais e melhor.', '["Longevidade saudável — viver mais com vitalidade — depende menos de ‘hacks’ isolados e mais de pilares integrados sustentados por décadas de pesquisa epidemiológica.","Sono reparador regula hormônios, repara DNA e consolida memória. Nutrição anti-inflamatória (vegetais, proteínas magras, gorduras boas) reduz marcadores de envelhecimento celular.","Movimento regular — combinação de aeróbico, força e mobilidade — preserva massa muscular, ossos e função metabólica após os 40 anos.","Gestão de estresse e conexões sociais impactam imunidade e risco de doenças crônicas tanto quanto tabagismo impacta negativamente. Solidão crônica associa-se a maior mortalidade.","Biomarcadores como glicemia, PCR-us, pressão arterial e composição corporal ajudam a ajustar hábitos antes de sintomas. Longevidade é processo mensurável — não sorte genética apenas."]'::jsonb, 'longevidade', 'Longevidade', 'Dra. Marina Alves', 'Medicina Preventiva', '8 min', '28 Mai 2026', true, false, '/logo-saude-bem.png', 'Os 5 pilares da longevidade que a ciência confirma | Guia Saúde & Bem', 'Descubra os hábitos com maior evidência científica para viver mais e melhor.', 'pilares, longevidade, 2026', '/logo-saude-bem.png', 'published');
insert into public.articles (id, slug, title, excerpt, content, category, category_label, author, author_role, read_time, published_at, featured, is_premium, cover_image_url, seo_title, seo_description, seo_keywords, og_image_url, status) values ('a1000001-0001-4001-8001-000000000010', 'biomarcadores-envelhecimento', 'Biomarcadores do envelhecimento saudável', 'Exames e indicadores que acompanham saúde metabólica, inflamação e vitalidade.', '["Envelhecimento saudável pode ser acompanhado por biomarcadores acessíveis em laboratórios de rotina. Tendências ao longo do tempo importam mais que um único resultado isolado.","Glicemia em jejum e HbA1c refletem saúde metabólica. Valores limítrofes precedem diabetes por anos — janela de oportunidade para mudança de estilo de vida.","PCR ultrassensível (PCR-us) indica inflamação crônica de baixo grau, associada a doenças cardiovasculares e declínio cognitivo. Dieta anti-inflamatória e exercício reduzem esse marcador.","Função tireoidiana (TSH, T4 livre), vitamina D e ferritina completam painel básico em muitos protocolos de medicina preventiva. Deficiências corrigíveis explicam fadiga e queda de performance.","Conteúdo premium do Clube Saúde & Bem aprofunda interpretação e planos personalizados — sempre em complemento ao acompanhamento médico, nunca como substituto."]'::jsonb, 'longevidade', 'Longevidade', 'Dr. Rafael Costa', 'Medicina Preventiva', '9 min', '1 Mai 2026', false, true, '/logo-saude-bem.png', 'Biomarcadores do envelhecimento saudável | Guia Saúde & Bem', 'Exames e indicadores que acompanham saúde metabólica, inflamação e vitalidade.', 'biomarcadores, envelhecimento', '/logo-saude-bem.png', 'published');
